import { Component, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-registro-negocio',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './registro-negocio.component.html',
  styleUrl: './registro-negocio.component.css'
})
export class RegistroNegocioComponent {
  nombre = '';
  correo = '';
  password = '';

  nombreNegocio = '';
  rubro = 'BARBERIA';
  telefonoFijoNegocio = '';
  departamentoNegocio = '';
  direccionNegocio = '';
  logoUrl = '';
  portadaUrl = '';

  cargando = signal(false);
  error = signal<string | null>(null);

  constructor(private auth: AuthService, private router: Router) {}

  continuar() {
    if (!this.nombre || !this.correo || !this.password || !this.nombreNegocio) {
      this.error.set('Completa al menos tu nombre, correo, contraseña y el nombre del negocio.');
      return;
    }
    this.error.set(null);
    this.cargando.set(true);

    this.auth.registro({
      nombre: this.nombre,
      correo: this.correo,
      password: this.password,
      rol: 'ADMIN_NEGOCIO',
      nombreNegocio: this.nombreNegocio,
      rubro: this.rubro,
      telefonoFijoNegocio: this.telefonoFijoNegocio,
      departamentoNegocio: this.departamentoNegocio,
      direccionNegocio: this.direccionNegocio,
      logoUrl: this.logoUrl,
      portadaUrl: this.portadaUrl,
    }).subscribe({
      next: () => {
        this.cargando.set(false);
        this.router.navigate(['/dashboard']);
      },
      error: err => {
        this.cargando.set(false);
        this.error.set(err?.error ?? 'No se pudo crear el negocio.');
      }
    });
  }
}
<div class="kutt-reg-shell">
  <div class="kutt-reg-card">
    <a routerLink="/login" class="kutt-back">← Volver</a>
    <h2>Registro de tu negocio</h2>

    <p class="kutt-section-label">Tus datos</p>
    <div class="kutt-field"><label>Tu nombre</label><input [(ngModel)]="nombre" name="nombre"></div>
    <div class="kutt-field"><label>Correo electrónico</label><input type="email" [(ngModel)]="correo" name="correo"></div>
    <div class="kutt-field"><label>Contraseña</label><input type="password" [(ngModel)]="password" name="password"></div>

    <p class="kutt-section-label">Datos del negocio</p>
    <div class="kutt-field"><label>Nombre del negocio</label><input [(ngModel)]="nombreNegocio" name="nombreNegocio"></div>

    <div class="kutt-field">
      <label>Rubro</label>
      <select [(ngModel)]="rubro" name="rubro">
        <option value="BARBERIA">Barbería</option>
        <option value="UNAS">Uñas</option>
        <option value="ESTETICA">Estética</option>
        <option value="SPA">Spa</option>
        <option value="OTRO">Otro</option>
      </select>
    </div>

    <div class="kutt-field"><label>Teléfono fijo del local</label><input [(ngModel)]="telefonoFijoNegocio" name="telefonoFijoNegocio"></div>
    <div class="kutt-field"><label>Departamento</label><input [(ngModel)]="departamentoNegocio" name="departamentoNegocio"></div>
    <div class="kutt-field"><label>Dirección</label><input [(ngModel)]="direccionNegocio" name="direccionNegocio"></div>
    <div class="kutt-field"><label>URL del logo del negocio</label><input [(ngModel)]="logoUrl" name="logoUrl" placeholder="https://..."></div>
    <div class="kutt-field"><label>URL de la foto de portada</label><input [(ngModel)]="portadaUrl" name="portadaUrl" placeholder="https://..."></div>

    <p class="kutt-error" *ngIf="error()">{{ error() }}</p>

    <button class="kutt-btn-primary" [disabled]="cargando()" (click)="continuar()">
      {{ cargando() ? 'Creando negocio...' : 'Continuar' }}
    </button>

    <p class="kutt-switch">¿Ya tienes cuenta? <a routerLink="/login">Inicia sesión</a></p>
  </div>
</div>
